#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
using namespace std;

struct Eleve {
    string nom;
    int note;
};

class ParNoteDecroissante {
public:
    bool operator()(const Eleve& a, const Eleve& b) const {
        return a.note > b.note;
    }
};

int main() {
    int n;
    cin >> n;
    vector<Eleve> v;
    for (int i = 0; i < n; ++i) {
        Eleve e;
        cin >> e.nom >> e.note;
        v.push_back(e);
    }
    sort(v.begin(), v.end(), ParNoteDecroissante());
    for (const Eleve& e : v)
        cout << e.nom << " " << e.note << "\n";
    return 0;
}

